import { test } from 'node:test';
import assert from 'node:assert/strict';
import { exportNames, handleExport } from '../src/server.js';

// CONTRIBUTING.md: only the holiday calendar may be shown to a guest. Every export is checked, so a new one
// that forgets requireRole fails here.
const OPEN_TO_GUESTS = ['holidays'];

for (const name of exportNames()) {
  test(`${name}: a guest ${OPEN_TO_GUESTS.includes(name) ? 'may' : 'may not'} download it`, () => {
    assert.equal(handleExport(name, { role: 'guest' }).status, OPEN_TO_GUESTS.includes(name) ? 200 : 403);
  });
  test(`${name}: the team downloads it`, () => {
    for (const role of ['admin', 'member']) assert.equal(handleExport(name, { role }).status, 200);
  });
}

