import { test } from 'node:test';
import assert from 'node:assert/strict';
import { handleExport } from '../src/server.js';

// #14: the invoices export is for the team only.
test('a guest may not download the invoices', () => {
  assert.equal(handleExport('invoices', { role: 'guest' }).status, 403);
});

test('a member downloads the invoices', () => {
  assert.equal(handleExport('invoices', { role: 'member' }).status, 200);
});

